// Hafif i18n altyapısı — varsayılan Türkçe, İngilizce opsiyonel.
// Dil değişince sayfa yeniden yüklenir (en basit ve güvenilir yaklaşım).
// Yeni metinleri t('anahtar') ile sarmalayarak kademeli olarak çevirilebilir hale getir.

export type Locale = 'tr' | 'en' | 'de' | 'fr' | 'es' | 'pt' | 'ja';

const STORAGE_KEY = 'concord_locale';

// Desteklenen diller. getLocale BUNA karşı doğrular — eskiden `v === 'en' ? 'en' : 'tr'`
// yazıyordu, yani ayarlardan Almanca seçmek localStorage'a 'de' yazıyor ama okuma onu
// 'tr'ye düşürüyordu: TR/EN dışındaki her dil SEÇİLEMİYORDU (sözlük dolu olsa bile).
const LOCALE_SET = new Set<string>(['tr', 'en', 'de', 'fr', 'es', 'pt', 'ja']);

export function getLocale(): Locale {
  const v = typeof localStorage !== 'undefined' ? localStorage.getItem(STORAGE_KEY) : null;
  return v && LOCALE_SET.has(v) ? (v as Locale) : 'tr';
}

export function setLocale(l: Locale) {
  localStorage.setItem(STORAGE_KEY, l);
  // Tüm metinler render anında okunduğu için en güvenli yenileme reload'dur.
  location.reload();
}

